public class TreeNode
{
    public int Val;
    public TreeNode? Left;
    public TreeNode? Right;
    public TreeNode(int val) { Val = val; }
}
public static class TreeSerializer
{
    public static int?[] ToLevelOrderArray(TreeNode? root)
    {
        if (root == null) return Array.Empty<int?>();
        var slots = new Dictionary<int, int>();
        var queue = new Queue<(TreeNode node, int index)>();
        queue.Enqueue((root, 0));
        var maxIndex = 0;
        while (queue.Count > 0)
        {
            var (node, index) = queue.Dequeue();
            slots[index] = node.Val;
            if (index > maxIndex) maxIndex = index;
            if (node.Left != null) queue.Enqueue((node.Left, 2 * index + 1));
            if (node.Right != null) queue.Enqueue((node.Right, 2 * index + 2));
        }
        var result = new int?[maxIndex + 1];
        foreach (var kv in slots) result[kv.Key] = kv.Value;
        return result;
    }
}

